Session(userId: string): string {
  const db = getDb();
  const token = generateToken();
  const sessionId = crypto.randomUUID();
  const expiresAt = Math.floor(Date.now() / 1000) + SESSION_EXPIRY_HOURS * 3600;

  db.run(
    `INSERT INTO sessions (id, user_id, token, expires_at) VALUES (?, ?, ?, ?)`,
    [sessionId, userId, token, expiresAt]
  );

  return token;
}

/**
 * Validate a session token and return the associated user.
 * @param token - The session token to validate
 * @returns The user ID if valid, null otherwise
 */
export function validateToken(token: string): string | null {
  const db = getDb();
  const now = Math.floor(Date.now() / 1000);

  const session = db.query(
    `SELECT user_id FROM sessions WHERE token = ? AND expires_at > ?`
  ).get(token, now) as { user_id: string } | undefined;

  return session?.user_id ?? null;
}

/**
 * Delete a session (logout).
 * @param token - The session token to invalidate
 */
export function deleteSession(token: string): void {

  const db = getDb();
  db.run(`DELETE FROM sessions WHERE token = ?`, [token]);
}

/**
 * Find a user by email.
 * @param email - The user's email
 * @returns The user record if found, null otherwise
 */
export function findUserByEmail(email: string): { id: string; email: string; password_hash: string } | null {
  const db = getDb();
  const user = db.query(`SELECT id, email, password_hash FROM users WHERE email = ?`).get(email) as
    | { id: string; email: string; password_hash: string }
    | undefined;

  return user ?? null;
}

/**
 * Find a user by ID.
 * @param id - The user's ID
 * @returns The user record if found, null otherwise
 */
export function findUserById(id: string): { id: string; email: string } | null {
  const db = getDb();
  const user = db.query(`SELECT id, email FROM users WHERE id = ?`).get(id) as
    | { id: string; email: string }
    | undefined;

  return user ?? null;
}

